  sqlFiles.sort();

  // Log each filename that would be applied
  console.log(`Found ${sqlFiles.length} migration(s) to apply:\n`);

  for (const file of sqlFiles) {
    console.log(`  - Applying: ${file}`);
  }

  console.log(`\nTotal migrations to apply: ${sqlFiles.length}`);
}

// Run the migration script
runMigrations();

