#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

const MIGRATIONS_DIR = './migrations';
const ENV_FILE = '.env.test';

/**
 * Parses a .env file and returns an object with the variables.
 * @param {string} envFilePath - Path to the .env file
 * @returns {Object} - Object with environment variables
 */
function parseEnvFile(envFilePath) {
  if (!fs.existsSync(envFilePath)) {
    return {};
  }

  const content = fs.readFileSync(envFilePath, 'utf8');
  const envVars = {};

  for (const line of content.split('\n')) {
    const trimmed = line.trim();
    // Skip empty lines and comments
    if (!trimmed || trimmed.startsWith('#')) {
      continue;
    }

    const equalIndex = trimmed.indexOf('=');
    if (equalIndex > -1) {
      const key = trimmed.substring(0, equalIndex).trim();
      const value = trimmed.substring(equalIndex + 1).trim();
      envVars[key] = value;
    }
  }

  return envVars;
}

/**
 * Resolves the database connection string from environment variables.
 * @returns {string|null} - The DATABASE_URL or null if not found
 */
function resolveConnectionString() {
  const envVars = parseEnvFile(ENV_FILE);
  return envVars.DATABASE_URL || null;
}

/**
 * Reads SQL migration files from the migrations directory and logs each filename
 * that would be applied, in order.
 */
function runMigrations() {
  // Resolve connection string
  const connectionString = resolveConnectionString();

  if (!connectionString) {
    console.error('Error: DATABASE_URL not found in .env.test');
    process.exit(1);
  }

  console.log('Connected to database successfully');
  console.log('');

  // Check if migrations directory exists
  if (!fs.existsSync(MIGRATIONS_DIR)) {
    console.log(`No migrations directory found at ${MIGRATIONS_DIR}`);
    return;
  }

  // Read all files from the migrations directory
  const files = fs.readdirSync(MIGRATIONS_DIR);

  // Filter for SQL files only
  const sqlFiles = files.filter(file => file.endsWith('.sql'));

  // Sort files in order (by filename, assuming they are named with version/date prefixes)
  sqlFiles.sort();

  // Log each filename that would be applied
  console.log(`Found ${sqlFiles.length} migration(s) to apply:\n`);

  for (const file of sqlFiles) {
    console.log(`  - Applying: ${file}`);
  }

  console.log(`\nTotal migrations to apply: ${sqlFiles.length}`);
}

// Run the migration script
runMigrations();

