/**
 * Database Migration Script
 * 
 * Reads SQL files from ./migrations/ directory and logs each filename
 * it would apply, in order (sorted alphabetically/naturally).
 */

const fs = require('fs');
const path = require('path');

const MIGRATIONS_DIR = path.join(__dirname, 'migrations');

/**
 * Get all SQL files from the migrations directory, sorted in order
 * @returns {string[]} Array of SQL filenames sorted by name
 */
function getMigrationFiles() {
  // Check if migrations directory exists
  if (!fs.existsSync(MIGRATIONS_DIR)) {
    console.log(`Migrations directory "${MIGRATIONS_DIR}" does not exist.`);
    console.log('No migrations to apply.');
    return [];
  }

  // Read all files from migrations directory
  const files = fs.readdirSync(MIGRATIONS_DIR);

  // Filter for SQL files only
  const sqlFiles = files.filter(file => file.endsWith('.sql'));

  // Sort files in order (natural sort for proper numerical ordering)
  sqlFiles.sort((a, b) => a.localeCompare(b, undefined, { numeric: true, sensitivity: 'base' }));

  return sqlFiles;
}

/**
 * Main migration function - logs each migration file that would be applied
 */
function migrate() {
  console.log('Starting migration check...');
  console.log(`Looking for SQL files in: ${MIGRATIONS_DIR}`);
  console.log('---');

  const migrationFiles = getMigrationFiles();

  if (migrationFiles.length === 0) {
    console.log('No migration files found.');
    console.log('---');
    console.log('Migration check complete.');
    return;
  }

  console.log(`Found ${migrationFiles.length} migration file(s):`);
  console.log('---');

  // Log each filename that would be applied, in order
  migrationFiles.forEach((filename, index) => {
    console.log(`  ${index + 1}. ${filename}`);
  });

  console.log('---');
  console.log('Migration check complete.');
}

// Run if executed directly
if (require.main === module) {
  migrate();
}

module.exports = { migrate, getMigrationFiles };

