      return valueParts.join('=').trim();
    }
  }
  return null;
}

/**
 * Reads SQL files from the migrations directory and logs each filename in order.
 */
function migrate() {
  // Read DATABASE_URL from .env.test
  const databaseUrl = getEnvValue(ENV_FILE, 'DATABASE_URL');
  if (databaseUrl) {
    console.log(`Connected to database: ${databaseUrl}`);
  } else {
    console.log('DATABASE_URL not found in .env.test');
  }

  // Check if migrations directory exists
  if (!fs.existsSync(MIGRATIONS_DIR)) {
    console.log('No migrations directory found. Creating one...');
    fs.mkdirSync(MIGRATIONS_DIR, { recursive: true });
    return;
  }

  // Read all files from the migrations directory
  const files = fs.readdirSync(MIGRATIONS_DIR);

  // Filter for SQL files and sort them in order
  const sqlFiles = files
    .filter(file => file.endsWith('.sql'))
    .sort();

  if (sqlFiles.length === 0) {
    console.log('No migration files found.');
    return;
  }

  // Log each filename that would be applied
  console.log(`Found ${sqlFiles.length} migration(s):`);
  sqlFiles.forEach((file, index) => {
    console.log(`  ${index + 1}. ${file}`);
  });
}

// Run the migration
migrate();
